    12  /* DATA/BDAT/B... commands */
    13
    14  struct cmd_data_context {
    15          struct istream *chunk_input;
    16          uoff_t chunk_size;
    17
    18          bool chunking:1;
    19          bool client_input:1;
    20          bool chunk_first:1;
    21          bool chunk_last:1;
