    24  static void
    25  smtp_server_cmd_data_size_limit_exceeded(struct smtp_server_cmd_ctx *cmd)
    26  {
    27          struct smtp_server_command *command = cmd->cmd;
    28
    29          smtp_server_command_fail(command, 552, "5.2.3",
    30                                   "Message size exceeds administrative limit");
    31  }
