   129  static void
   130  cmd_data_destroy(struct smtp_server_cmd_ctx *cmd,
   131                   struct cmd_data_context *data_cmd)
   132  {
   133          struct smtp_server_connection *conn = cmd->conn;
   134          struct smtp_server_command *command = cmd->cmd;
   135
   136          i_assert(data_cmd != NULL);
   137
   138          if (data_cmd->chunk_last ||
   139                  !smtp_server_command_replied_success(command)) {
   140                  /* clean up */
   141                  i_stream_destroy(&conn->state.data_input);
   142                  i_stream_destroy(&conn->state.data_chain_input);
   143                  conn->state.data_chain = NULL;
   144          }
   145
   146          i_stream_unref(&data_cmd->chunk_input);
   147  }
