   149  static void
   150  cmd_data_replied_one(struct smtp_server_cmd_ctx *cmd,
   151                       struct cmd_data_context *data_cmd ATTR_UNUSED)
   152  {
   153          struct smtp_server_connection *conn = cmd->conn;
   154          struct smtp_server_transaction *trans = conn->state.trans;
   155          struct smtp_server_recipient **rcptp;
   156
   157          if (trans == NULL || !array_is_created(&trans->rcpt_to))
   158                  return;
   159
   160          array_foreach_modifiable(&trans->rcpt_to, rcptp)
   161                  smtp_server_recipient_data_replied(*rcptp);
   162  }
