   164  static void
   165  cmd_data_replied(struct smtp_server_cmd_ctx *cmd,
   166                   struct cmd_data_context *data_cmd ATTR_UNUSED)
   167  {
   168          struct smtp_server_connection *conn = cmd->conn;
   169          struct smtp_server_command *command = cmd->cmd;
   170
   171          i_assert(conn->state.pending_data_cmds > 0);
   172          conn->state.pending_data_cmds--;
   173
   174          smtp_server_command_input_lock(cmd);
   175          if (!smtp_server_command_replied_success(command))
   176                  smtp_server_command_input_unlock(cmd);
   177  }
