   179  static void
   180  cmd_data_completed(struct smtp_server_cmd_ctx *cmd,
   181                     struct cmd_data_context *data_cmd)
   182  {
   183          struct smtp_server_connection *conn = cmd->conn;
   184
   185          i_assert(data_cmd != NULL);
   186          i_stream_unref(&data_cmd->chunk_input);
   187
   188          i_assert(conn->state.trans != NULL);
   189          smtp_server_transaction_finished(conn->state.trans, cmd);
   190
   191          /* reset state */
   192          smtp_server_connection_reset_state(conn);
   193  }
