   195  static void
   196  cmd_data_chunk_replied(struct smtp_server_cmd_ctx *cmd,
   197                         struct cmd_data_context *data_cmd)
   198  {
   199          struct smtp_server_connection *conn = cmd->conn;
   200          struct smtp_server_command *command = cmd->cmd;
   201
   202          i_assert(data_cmd != NULL);
   203
   204          i_assert(conn->state.pending_data_cmds > 0);
   205          conn->state.pending_data_cmds--;
   206
   207          i_assert(smtp_server_command_is_replied(command));
   208          if (!smtp_server_command_replied_success(command) &&
   209              conn->state.pending_data_cmds == 0)
   210                  conn->state.data_failed = TRUE;
   211  }
