   213  static void
   214  cmd_data_chunk_completed(struct smtp_server_cmd_ctx *cmd,
   215                           struct cmd_data_context *data_cmd ATTR_UNUSED)
   216  {
   217          struct smtp_server_connection *conn = cmd->conn;
   218          struct smtp_server_command *command = cmd->cmd;
   219
   220          if (!smtp_server_command_replied_success(command))
   221                  conn->state.data_failed = TRUE;
   222  }
