   224  static void
   225  cmd_data_chunk_finish(struct smtp_server_cmd_ctx *cmd)
   226  {
   227          struct smtp_server_command *command = cmd->cmd;
   228          struct cmd_data_context *data_cmd = command->data;
   229
   230          smtp_server_command_input_lock(cmd);
   231          i_stream_unref(&data_cmd->chunk_input);
   232
   233          /* re-check transaction state (for BDAT/B... command) */
   234          if (!smtp_server_connection_data_check_state(cmd))
   235                  return;
   236
   237          smtp_server_reply(cmd, 250, "2.0.0",
   238                  "Added %"PRIuUOFF_T" octets", data_cmd->chunk_size);
   239  }
