   241  static void cmd_data_input_error(struct smtp_server_cmd_ctx *cmd)
   242  {
   243          struct smtp_server_connection *conn = cmd->conn;
   244          struct smtp_server_command *command = cmd->cmd;
   245          struct cmd_data_context *data_cmd = command->data;
   246          struct istream *data_input = conn->state.data_input;
   247          const char *error;
   248
   249          conn->state.data_failed = TRUE;
   250
   251          if (!data_cmd->client_input) {
   252                  if (!smtp_server_command_is_replied(command)) {
   253                          smtp_server_command_fail(command,
   254                                  400, "4.0.0", "Failed to add data");
   255                  }
   256                  return;
   257          }
   258
   259          error = i_stream_get_disconnect_reason(data_input);
   260          e_debug(conn->event, "Connection lost during data transfer: %s", error);
   261          smtp_server_connection_close(&conn, error);
   262  }
   263
   264  static int cmd_data_do_handle_input(struct smtp_server_cmd_ctx *cmd)
   265  {
   266          struct smtp_server_connection *conn = cmd->conn;
   267          const struct smtp_server_callbacks *callbacks = conn->callbacks;
   268          struct smtp_server_command *command = cmd->cmd;
   269          struct cmd_data_context *data_cmd = command->data;
   270          int ret;
   271
   272          i_assert(data_cmd != NULL);
   273
   274          i_assert(callbacks != NULL &&
   275                   callbacks->conn_cmd_data_continue != NULL);
   276          ret = callbacks->conn_cmd_data_continue(conn->context,
   277                  cmd, conn->state.trans);
   278          if (ret >= 0) {
   279                  if (!smtp_server_cmd_data_check_size(cmd)) {
   280                          return -1;
   281                  } else if (!i_stream_have_bytes_left(conn->state.data_input)) {
   282                          e_debug(cmd->event, "End of data");
   283                          smtp_server_transaction_received(
   284                                  conn->state.trans,
   285                                  conn->state.data_input->v_offset);
   286                          smtp_server_command_input_lock(cmd);
   287                          smtp_server_connection_timeout_stop(conn);
   288                  } else if (!data_cmd->chunk_last &&
   289                          !i_stream_have_bytes_left(data_cmd->chunk_input)) {
   290                          e_debug(cmd->event, "End of chunk");
   291                          cmd_data_chunk_finish(cmd);
   292                  } else if (i_stream_get_data_size(
   293                          conn->state.data_input) > 0) {
   294                          e_debug(cmd->event, "Not all client data read");
   295                          smtp_server_connection_timeout_stop(cmd->conn);
   296                  } else {
   297                          smtp_server_connection_timeout_start(cmd->conn);
   298                  }
   299          } else {
   300                  if (conn->state.data_input->stream_errno != 0) {
   301                          cmd_data_input_error(cmd);
   302                          return -1;
   303                  }
   304                  /* command is waiting for external event or it failed */
   305                  i_assert(smtp_server_command_is_replied(command));
   306          }
   307
   308          return 1;
   309  }
   310
   311  static int cmd_data_handle_input(struct smtp_server_cmd_ctx *cmd)
   312  {
   313          struct smtp_server_connection *conn = cmd->conn;
   314          struct smtp_server_command *command = cmd->cmd;
   315          int ret;
   316
   317          if (!smtp_server_cmd_data_check_size(cmd))
   318                  return -1;
   319
   320          smtp_server_connection_ref(conn);
   321          smtp_server_command_ref(command);
   322
   323          /* continue reading from client */
   324          ret = cmd_data_do_handle_input(cmd);
   325
   326          smtp_server_command_unref(&command);
   327          smtp_server_connection_unref(&conn);
   328
   329          return ret;
   330  }
   331
   332  static void cmd_data_input(struct smtp_server_cmd_ctx *cmd)
   333  {
   334          smtp_server_connection_timeout_reset(cmd->conn);
   335          (void)cmd_data_handle_input(cmd);
   336  }
