   227  void i_stream_snapshot_free(struct istream_snapshot **_snapshot)
   228  {
   229          struct istream_snapshot *snapshot = *_snapshot;
   230
   231          if (*_snapshot == NULL)
   232                  return;
   233          *_snapshot = NULL;
   234
   235          i_stream_snapshot_free(&snapshot->prev_snapshot);
