   248  ssize_t i_stream_read(struct istream *stream)
   249  {
   250          struct istream_private *_stream = stream->real_stream;
   251          ssize_t ret;
   252  #ifdef DEBUG
   253          unsigned char prev_buf[4];
   254          const unsigned char *prev_data = _stream->buffer;
   255          size_t prev_skip = _stream->skip, prev_pos = _stream->pos;
   256          bool invalid = i_stream_is_buffer_invalid(_stream);
   257
   258          i_assert(prev_skip <= prev_pos);
   259          if (invalid)
   260                  ;
   261          else if (prev_pos - prev_skip <= 4)
   262                  memcpy(prev_buf, prev_data + prev_skip, prev_pos - prev_skip);
   263          else {
   264                  memcpy(prev_buf, prev_data + prev_skip, 2);
   265                  memcpy(prev_buf+2, prev_data + prev_pos - 2, 2);
   266          }
   267  #endif
   268
   269          if (_stream->skip != _stream->pos || _stream->prev_snapshot != NULL) {
   270                  _stream->prev_snapshot =
   271                          _stream->snapshot(_stream, _stream->prev_snapshot);
   272          }
   273          ret = i_stream_read_memarea(stream);
   274          if (ret > 0)
   275                  i_stream_snapshot_free(&_stream->prev_snapshot);
   276  #ifdef DEBUG
   277          else if (!invalid) {
   278                  i_assert((_stream->pos - _stream->skip) == (prev_pos - prev_skip) ||
   279                           prev_pos == prev_skip);
   280                  if (prev_pos - prev_skip <= 4)
   281                          i_assert(memcmp(prev_buf, prev_data + prev_skip, prev_pos - prev_skip) == 0);
   282                  else {
   283                          i_assert(memcmp(prev_buf, prev_data + prev_skip, 2) == 0);
   284                          i_assert(memcmp(prev_buf+2, prev_data + prev_pos - 2, 2) == 0);
   285                  }
   286          }
   287  #endif
   288          return ret;
   289  }
