   291  ssize_t i_stream_read_memarea(struct istream *stream)
   292  {
   293          struct istream_private *_stream = stream->real_stream;
   294          size_t old_size;
   295          ssize_t ret;
   296
   297          if (unlikely(stream->closed || stream->stream_errno != 0)) {
   298                  stream->eof = TRUE;
   299                  errno = stream->stream_errno;
   300                  return -1;
   301          }
